// Unknown properties resolve to another permissive node, so renderer-only
// plumbing (shadow cameras, uniforms, layers) costs nothing to stub. Anything
// beginning with "is" stays undefined — three uses isMesh/isLight as type
// tests, and a truthy answer would make every stub claim to be every type.
function permissive(base) {
  return new Proxy(base, {
    get(t, k) {
      if (k in t) return t[k];
      if (typeof k !== 'string') return undefined;
      if (k.startsWith('is') || k === 'then' || k === 'nodeType') return undefined;
      // callable, because half of what gets reached for is a method
      const fn = function () { return fn; };
      Object.assign(fn, { value: 0, x: 0, y: 0, z: 0, left: 0, right: 0,
        top: 0, bottom: 0, near: 0, far: 0, bias: 0, radius: 0, enabled: false,
        set(){ return fn; }, copy(){ return fn; }, setScalar(){ return fn; },
        multiplyScalar(){ return fn; }, updateProjectionMatrix(){}, dispose(){} });
      const made = permissive(fn);
      t[k] = made;
      return made;
    },
    set(t, k, v) { t[k] = v; return true; },
  });
}

