// Geometries that KNOW WHAT THEY ARE. three's own carry a .type and their
// constructor arguments in .parameters, and game code reads both (bigPanel
// picks the frame out of the slate by asking for BoxGeometry). A stub that
// answers a permissive proxy to `.type` makes every such test quietly false,
// and makes it impossible to ask the scene a question like "which of these is
// a cone, and which way up is it?"
const geomKind = (name, argNames) => class extends Anything {
  constructor(...a) {
    super();
    this.type = name;
    this.parameters = {};
    argNames.forEach((k, i) => { this.parameters[k] = a[i]; });
  }
};
